import{_ as s}from"./chunks/repeat-times.dRbhJCV7.js";import{_ as n,o as p,a as t,b as l}from"./app.DKoEZOcr.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopy（UBToL1高维切分数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_UBToL1_highdim_split"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_UBToL1_highdim_split.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_UBToL1_highdim_split.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_UBToL1_highdim_split.md"};function i(e,a,o,d,r,_){return p(),t("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>DataCopy（UBToL1高维切分数据搬运）</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为软件仿真实现，是在Matmul高阶API的基础上，利用Matmul高阶API中的workspace GM空间作为数据中转空间，数据先搬入GM，再搬入L1 Buffer。因此，在使用本接口时，需要先使用REGISTER_MATMUL注册高阶API。</p></div><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口实现将矩阵从Unified Buffer（UB，TPosition为VECIN/VECCALC/VECOUT）搬运至L1 Buffer，支持非连续搬运和连续搬运，数据搬运时格式和内容保持不变。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 同时支持非连续搬运和连续搬运</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。源操作数和目的操作数的数据类型保持一致。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，存储位置为L1 Buffer，起始地址要求32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，存储位置为UB（TPosition为VECIN/VECCALC/VECOUT），起始地址要求32字节对齐。</td></tr><tr><td>repeatParams</td><td>输入</td><td>搬运参数，DataCopyParams类型。通过该参数可配置搬运的数据块大小、个数、间隔等信息，同时支持非连续和连续搬运。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>。</td></tr></tbody></table><p><strong>表3</strong> DataCopyParams结构体参数定义</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>blockCount</td><td>待搬运的连续传输数据块个数。uint16_t类型，取值范围：blockCount∈[1, 4095]。</td></tr><tr><td>blockLen</td><td>待搬运的每个连续传输数据块长度，单位为DataBlock（32字节）。uint16_t类型，取值范围：blockLen∈[1, 65535]。</td></tr><tr><td>srcGap</td><td>源操作数相邻连续数据块的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为DataBlock（32字节）。uint16_t类型。</td></tr><tr><td>dstGap</td><td>目的操作数相邻连续数据块间的间隔（前面一个数据块的尾与后面数据块的头的间隔），单位为DataBlock（32字节）。uint16_t类型。</td></tr></tbody></table><p>下图呈现了DataCopyParams结构体参数的使用方法，样例中完成了2个连续传输数据块的搬运，每个数据块含有8个DataBlock，源操作数相邻数据块之间无间隔，目的操作数相邻数据块尾与头之间间隔1个DataBlock。</p><p><strong>图 1</strong> DataCopyParams结构体参数使用示意图<a id="fig_repeat_times_demo"></a></p><p><img src="`+s+`" alt title="DataCopyParams结构体参数使用示意图"></p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>源矩阵和目的矩阵支持的数据类型保持一致。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，支持数据类型为：bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64。</p></div><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、half、bfloat16_t、float、double。</p></div><div data-filter="910b"><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、half、bfloat16_t、float、double。</p></div><div data-filter="310p"><p>针对Atlas 推理系列产品AI Core，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t、half、float、double。</p></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>如果需要执行多个DataCopy指令，且DataCopy的目的地址存在重叠，需要通过调用<a href="../../sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier(ISASI)</a>来插入同步指令，保证多个DataCopy指令的串行化，防止出现异常数据。</p></li><li><p>如果搬运的目的地址L1 Buffer存在重叠，两条搬运指令之间需要调用PipeBarrier&lt;PIPE_MTE2&gt;()添加MTE2搬入流水的同步。</p></li></ul><div data-filter="A3,910b"><ul><li><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品；</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品；</p></div><p>在跨卡通信算子开发场景，DataCopy类接口支持跨卡数据搬运，仅支持HCCS物理链路，不支持其他通路；开发者开发过程中，需要关注涉及卡间通信的物理通路，可通过npu-smi info -t topo命令查询HCCS物理链路。</p></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，在UB-&gt;L1 Buffer的数据搬运时，可以通过配置编译选项<a href="../../../../../guide/programming_guide/compilation_and_execution/operator_compilation/ai_core_operator_compilation.html#%E5%86%85%E7%BD%AE%E7%BC%96%E8%AF%91%E5%AE%8F%E5%BC%80%E5%85%B3">ENABLE_CV_COMM_VIA_SSBUF</a>来选择两种搬运通路，当ENABLE_CV_COMM_VIA_SSBUF配置为true时，使用SSBuffer进行通信，数据通过UB-&gt;L1 Buffer之间的硬件通道进行搬运（推荐），参考样例<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_ub2l1">硬通道搬运</a>；当ENABLE_CV_COMM_VIA_SSBUF为false时，数据搬运到L1 Buffer经过GM，该场景下需要借助Matmul高阶API进行注册操作。</li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>示例场景如<a href="#fig_repeat_times_demo">图 1</a>所示。</p><p>示例代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">8</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dataBlockElemCount</span><span class="p">;</span>

<span class="c1">// 源操作数：UB，2个数据块在源端紧密排列，每块8个DataBlock，共16个DataBlock。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECIN</span><span class="p">,</span><span class="w"> </span><span class="n">ubAddr</span><span class="p">,</span><span class="w"> </span><span class="n">srcElemCount</span><span class="p">);</span>

<span class="c1">// 目的操作数：L1 Buffer，两个目的数据块之间预留1个DataBlock间隔，总跨度为17个DataBlock。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">a1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyParams</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">;</span>
<span class="c1">// 搬运2个连续传输数据块。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// 每个数据块长度为8个DataBlock，即256B，等于128个half。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="c1">// 源UB相邻数据块尾与头之间无间隔，两个数据块紧密读取。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">srcGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 目的A1相邻数据块尾与头之间间隔1个DataBlock，即32B，等于16个half。</span>
<span class="n">repeatParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=n(c,[["render",i]]);export{A as __pageData,m as default};
